    # test the_meadow_can_be_won (hop/tests/runs.slg:42)
    # @why the meadow is winnable, with every gem, without losing a life
    def self.the_meadow_can_be_won
      Hop::World.start(1)
      Hop::Tests::Runs.meadow_win.each do |h|
        Spec::Ranges.list((1..h.ticks)).each do |i|
          Hop::World.step(Hop::Tests::Runs.pad_of(h.keys))
        end
      end
      Spec.assert(Hop::World.mode == Hop::Model::Mode::Won)
      Spec.assert(Hop::World.ticks == 316)
      Spec.assert(Hop::World.taken.size == 3)
      Spec.assert(Hop::World.lives == 3)
    end
    SUITE.test("hop.tests.runs.the_meadow_can_be_won", method(:the_meadow_can_be_won))

    # test the_ridge_can_be_won (hop/tests/runs.slg:54)
    # @why the ridge is winnable too
    def self.the_ridge_can_be_won
      Hop::World.start(2)
      Hop::Tests::Runs.ridge_win.each do |h|
        Spec::Ranges.list((1..h.ticks)).each do |i|
          if Hop::World.mode == Hop::Model::Mode::Playing
            Hop::World.step(Hop::Tests::Runs.pad_of(h.keys))
          end
        end
      end
      Spec.assert(Hop::World.mode == Hop::Model::Mode::Won)
      Spec.assert(Hop::World.ticks == 549)
      Spec.assert(Hop::World.taken.size == 3)
      Spec.assert(Hop::World.lives == 3)
    end
    SUITE.test("hop.tests.runs.the_ridge_can_be_won", method(:the_ridge_can_be_won))

    SUITE.case(
